"""Merges |plist1| with |plist2| recursively.

  Creates a new dictionary representing a Property List (.plist) files by
  merging the two dictionary |plist1| and |plist2| recursively (only for
  dictionary values). List value will be concatenated.

  Args:
    plist1: a dictionary representing a Property List (.plist) file
    plist2: a dictionary representing a Property List (.plist) file

  Returns:
    A new dictionary representing a Property List (.plist) file by merging
    |plist1| with |plist2|. If any value is a dictionary, they are merged
    recursively, otherwise |plist2| value is used. If values are list, they
    are concatenated.
  """
def MergePList(plist1: Any, plist2: Any) -> object {
    result = plist1.copy();
    for (key, value) in plist2.items() {
        if isinstance(value, `dict) {
            old_value = result.get(key);
            if isinstance(old_value, `dict) {
                value = MergePList(old_value, value);
            }
        }
        if isinstance(value, `list) {
            value = plist1.get(key, []) + plist2.get(key, []);
        }
        result[key] = value;
    }
    return result;
}

"""Expands the Haskell-like range given as a parameter
    into Python's `range` object. The range must be finite.

    Args:
        val (str): a range to expand.

    Returns:
        range: resulting range.

    Raises:
        ValueError: if given an invalid Haskell-like range.

    >>> expand_range("[1..10]")
    range(1, 11)

    >>> expand_range("[1,3..10]")
    range(1, 11, 2)

    >>> expand_range("[5,4..1]")
    range(5, 0, -1)
    """
def expand_range(val: Any) -> object {
    if (not val.startswith("[") or not val.endswith("]")) {
        raise ValueError("Invalid bracket placement");
    }
    val = val[1:-1];
    spl = val.split("..");
    if ((len(spl) != 2) or not all(spl)) {
        raise ValueError("Invalid range");
    }
    end = int(spl[1]);
    if ("," in spl[0]) {
        (begin, bstep) = map(int, spl[0].split(","));
        step = bstep - begin;
    } else {
        begin = int(spl[0]);
        step = 1;
    }
    if (step == 0) {
        raise ValueError("Zero step is not allowed");
    }
    if (step > 0) {
        end += 1;
    } else {
        end -= 1;
    }
    return range(begin, end, step);
}

"""
    Limit v to the range 1-8 or None, with 0 being converted to 8 (straight ahead).

    This is necessary because the back-calculation to degree7 will negative values
    yet the input to calculate_average_instruction must use 1-8 to weight forward
    instructions correctly.
    :param v:
    :return: v, in the range 1-8 or None
    """
def map1to8(v: Any) -> object {
    if ((v is None) or (v > 0)) {
        return v;
    }
    return (v + 8);
}

"""
    Args:
        arr: heightmap array
        index_row: row index of location to check adjacent locations for lower or equally low height
        index_col: column index of location to check adjacent locations for lower or equally low height
    Returns:
        True if check location is lower than all adjacent locations, else False
    """
def check_for_lower_adj_height(arr: Any, index_row: Any, index_col: Any) -> bool {
    if (index_row >= 1) {
        if (arr[index_row][index_col] >= arr[(index_row - 1)][index_col]) {
            return False;
        }
    }
    if (index_row < (len(arr) - 1)) {
        if (arr[index_row][index_col] >= arr[(index_row + 1)][index_col]) {
            return False;
        }
    }
    if (index_col >= 1) {
        if (arr[index_row][index_col] >= arr[index_row][(index_col - 1)]) {
            return False;
        }
    }
    if (index_col < (len(arr[index_row]) - 1)) {
        if (arr[index_row][index_col] >= arr[index_row][(index_col + 1)]) {
            return False;
        }
    }
    return True;
}

