    }
    r = `list();
    s = `list();
    s.append((0, l));
    while s {
        (i, l) = s.pop();
        while (i < len(l)) {
            while is_sequence(l[i]) {
                if not l[i] {
                    break;
                } elif make_flat(s) {
                    s.append(((i + 1), l));
                    l = l[i];
                    i = 0;
                } else {
                    r.append(l[i]);
                    break;
                }
            } else {
                r.append(l[i]);
            }
            i += 1;
        }
    }
    try {
        return `type(l)(r);
    } except TypeError {
        return r;
    }
}

